insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('f8d8bwnmba', 'daily:wuerzburg-dom:1610-michael-kern-the-younger-pulpit-of-w-rzburg-cathedral', 'Pulpit of Würzburg Cathedral', 'Michael Kern the Younger', 1610, '1609–1610', null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/f8d8bwnmba.jpg', 'Michael Kern the Younger carved this pulpit in 1609 and 1610. For centuries the sermon came from up here, above the heads of the congregation.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('unmv9rqja6', 'daily:wuerzburg-dom:1981-andreas-moritz-menorah', 'Menorah', 'Andreas Moritz', 1981, null, null, 'metal', 'Würzburg Cathedral (Kiliansdom)', 3, 'object', 'https://nambatu.github.io/circart-preview/art/unmv9rqja6.jpg', 'The seven-branched candelabrum stands in the middle of the nave. Andreas Moritz made it in 1981.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('2hat3rgzjg', 'daily:wuerzburg-dom:1499-tilman-riemenschneider-tomb-of-prince-bishop-rudolf-von-scheren', 'Tomb of Prince-Bishop Rudolf von Scherenberg', 'Tilman Riemenschneider', 1499, '1496–1499', null, 'marble', 'Würzburg Cathedral (Kiliansdom)', 2, 'sculpture', 'https://nambatu.github.io/circart-preview/art/2hat3rgzjg.jpg', 'Rudolf von Scherenberg died in 1495, and Riemenschneider got the commission a year later. The marble monument went up in 1499 and shows the bishop as a very old man, wrinkles and all.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('38up9vv29h', 'daily:wuerzburg-dom:1623-michael-kern-attributed-tomb-of-jakob-baur-von-eiseneck', 'Tomb of Jakob Baur von Eiseneck', 'Michael Kern (attributed)', 1623, '1623, attributed to Michael Kern', null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/38up9vv29h.jpg', 'Jakob Baur von Eiseneck was a colonel in the prince-bishop''s service. He died in July 1621 near Rozvadov in Bohemia, early in the Thirty Years'' War, and his tomb followed in 1623.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('d8dw8kcehs', 'daily:wuerzburg-dom:1279-master-eckart-of-worms-baptismal-font', 'Baptismal font', 'Master Eckart of Worms', 1279, null, null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'object', 'https://nambatu.github.io/circart-preview/art/d8dw8kcehs.jpg', 'Master Eckart from Worms made this font in 1279. Its sides are covered with figures and scenes, so it is worth walking all the way round it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('hs4nuryjuw', 'daily:wuerzburg-dom:1706-giovanni-pietro-magni-stucco-ceiling-of-the-crossing', 'Stucco ceiling of the crossing', 'Giovanni Pietro Magni', 1706, '1701–1706', 'Baroque', 'stucco', 'Würzburg Cathedral (Kiliansdom)', 3, 'architecture', 'https://nambatu.github.io/circart-preview/art/hs4nuryjuw.jpg', 'Giovanni Pietro Magni and a team of stucco workers from Ticino covered the church in baroque decoration between 1701 and 1706. The plain walls of the old church disappeared under swirls of white and gold.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('smb836nzqh', 'daily:wuerzburg-dom:1420-unknown-master-piet', 'Pietà', 'Unknown master', 1420, 'around 1410–1420 (sources differ)', 'International Gothic', null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/smb836nzqh.jpg', 'Mary holds her dead son on her lap. The sources date this Pietà to around 1410 to 1420 and name no sculptor.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('u8kyytsg6y', 'daily:wuerzburg-dom:1967-otto-sonnleitner-kilian-portal', 'Kilian Portal', 'Otto Sonnleitner', 1967, null, null, 'portal', 'Würzburg Cathedral (Kiliansdom)', 3, 'architecture', 'https://nambatu.github.io/circart-preview/art/u8kyytsg6y.jpg', 'Otto Sonnleitner made this portal in 1967, the year the rebuilt cathedral was consecrated again. Since then the church has been dedicated to Kilian and his companions.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('esdap5vn63', 'daily:wuerzburg-dom:1736-balthasar-neumann-sch-nborn-chapel', 'Schönborn Chapel', 'Balthasar Neumann', 1736, '1721–1736', 'Baroque', null, 'Würzburg Cathedral (Kiliansdom)', 2, 'architecture', 'https://nambatu.github.io/circart-preview/art/esdap5vn63.jpg', 'Balthasar Neumann began the burial chapel of the Schönborn family in 1721. The shell stood by 1724, and the chapel was finished in 1736.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7acmeaj58r', 'daily:wuerzburg-dom:1075-bishops-bruno-and-adalbero-w-rzburg-cathedral', 'Würzburg Cathedral', 'Bishops Bruno and Adalbero', 1075, 'built 1040–1075', null, 'building', 'Würzburg Cathedral (Kiliansdom)', 2, 'architecture', 'https://nambatu.github.io/circart-preview/art/7acmeaj58r.jpg', 'Bishop Bruno started the church in 1040, and it was finished under Bishop Adalbero in 1075. Two older cathedrals had stood here before it, and both were damaged by fire.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-07', 'wuerzburg-dom', 'One cathedral, many centuries', 'Ein Dom, viele Jahrhunderte', 'Today we walk through Würzburg Cathedral. Nearly a thousand years of art stand side by side in it, from the Middle Ages to after the war. We start at the pulpit and walk down the middle of the nave towards a tall candelabrum.', 'Heute gehen wir durch den Würzburger Dom. Darin stehen fast tausend Jahre Kunst nebeneinander, vom Mittelalter bis nach dem Krieg. Wir beginnen an der Kanzel und gehen durch die Mitte des Langhauses auf einen hohen Leuchter zu.', 'On 16 March 1945 bombs and fire hit the cathedral, and in February 1946 its north wall collapsed. The rebuilt church was consecrated again on 6 May 1967. That is why old and new art stand so close together here today.', 'Am 16. März 1945 trafen Bomben und Feuer den Dom, und im Februar 1946 stürzte seine Nordwand ein. Am 6. Mai 1967 wurde die wiederaufgebaute Kirche neu geweiht. Deshalb stehen alte und neue Kunst hier heute so dicht beieinander.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 0, 'f8d8bwnmba', null, null, 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 1, 'unmv9rqja6', 'Now walk along the pillars on the left, where the prince-bishops keep watch.', 'Geh jetzt an den Pfeilern links entlang, wo die Fürstbischöfe Wache halten.', 'Photo: José Luiz, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 2, '2hat3rgzjg', 'Riemenschneider lived and worked in Würzburg, and he is buried in the city too. A few pillars on, a soldier waits.', 'Riemenschneider lebte und arbeitete in Würzburg und ist auch hier begraben. Ein paar Pfeiler weiter wartet ein Soldat.', 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 3, '38up9vv29h', 'It was probably carved by Michael Kern, from the same family of sculptors as the pulpit. Now cross over to the font, where the city''s children are baptised.', 'Vermutlich stammt es von Michael Kern, aus derselben Bildhauerfamilie wie die Kanzel. Jetzt geht es hinüber zum Taufbecken, an dem die Kinder der Stadt getauft werden.', 'Photo: Nilaxus, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 4, 'd8dw8kcehs', 'From the font we look straight up, to the white ceiling over the crossing.', 'Vom Taufbecken aus schauen wir direkt nach oben, zur weißen Decke über der Vierung.', 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 5, 'hs4nuryjuw', 'Below all that white and gold sits a quiet figure of grief in front of a golden wall.', 'Unter all dem Weiß und Gold sitzt eine stille Figur der Trauer vor einer goldenen Wand.', 'Photo: José Luiz, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 6, 'smb836nzqh', 'Now we step outside for a moment, to the side door on Kiliansplatz.', 'Jetzt gehen wir kurz hinaus, zum Seitenportal am Kiliansplatz.', 'Photo: Klaus Bärwinkel, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 7, 'u8kyytsg6y', 'Back inside, the north transept leads into a chapel built for one powerful family.', 'Zurück drinnen führt das nördliche Querhaus in eine Kapelle, die für eine mächtige Familie gebaut wurde.', 'Photo: Dietmar Rabich, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 8, 'esdap5vn63', 'Through the chapel we leave the cathedral. Turn around one last time and look at the whole church.', 'Durch die Kapelle verlassen wir den Dom. Dreh dich ein letztes Mal um und schau dir die ganze Kirche an.', 'Photo: Dguendel, CC BY 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 9, '7acmeaj58r', 'And that is the end of our walk.', 'Damit endet unser Rundgang.', 'Photo: Imaschke, CC BY-SA 4.0');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7drh4hwm49', 'daily:written-out:1705-maria-sibylla-merian-spiders-ants-and-a-hummingbird-on-a-guav', 'Spiders, ants and a hummingbird on a guava branch (Metamorphosis insectorum Surinamensium)', 'Maria Sibylla Merian', 1705, 'published in Amsterdam in 1705', null, 'hand-coloured engraving', 'Metamorphosis insectorum Surinamensium (book)', 2, 'drawing', 'https://nambatu.github.io/circart-preview/art/7drh4hwm49.jpg', 'Maria Sibylla Merian sailed to Suriname with her daughter Dorothea to watch insects grow up on their own plants. Back in Amsterdam she published her big book about them in 1705.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('4uwrrhee7q', 'daily:written-out:1555-sofonisba-anguissola-the-chess-game', 'The Chess Game', 'Sofonisba Anguissola', 1555, null, 'Mannerism', 'oil on canvas', 'National Museum, Poznań', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/4uwrrhee7q.jpg', 'Sofonisba Anguissola painted three of her sisters at a game of chess while a maid looks on. She signed and dated the picture on the edge of the chessboard.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('mj9ubupv5k', 'daily:written-out:1907-hilma-af-klint-the-ten-largest-no-7-adulthood', 'The Ten Largest, No. 7, Adulthood', 'Hilma af Klint', 1907, null, 'Abstract art', 'tempera on paper mounted on canvas', 'Hilma af Klint Foundation, Stockholm', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/mj9ubupv5k.jpg', 'This painting is more than three metres tall. It belongs to a series of ten about the ages of a human life, from childhood to old age.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('g9dab98dr3', 'daily:written-out:1630-judith-leyster-self-portrait', 'Self-Portrait', 'Judith Leyster', 1630, 'about 1630', 'Dutch Golden Age', 'oil on canvas', 'National Gallery of Art, Washington', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/g9dab98dr3.jpg', 'Judith Leyster turns round from her easel as if you had just walked into her studio. She was one of very few women in the Haarlem painters'' guild and had pupils of her own.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7a5wukj2sf', 'daily:written-out:1855-rosa-bonheur-the-horse-fair', 'The Horse Fair', 'Rosa Bonheur', 1855, '1852–1855', 'Realism', 'oil on canvas', 'The Metropolitan Museum of Art, New York', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/7a5wukj2sf.jpg', 'The canvas is about five metres wide. To study the horses at the Paris horse market, Rosa Bonheur went there in men''s clothes, which in her day needed a police permit.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('rh87rnegar', 'daily:written-out:1577-lavinia-fontana-self-portrait-at-the-clavichord-with-a-s', 'Self-Portrait at the Clavichord with a Servant', 'Lavinia Fontana', 1577, null, 'Mannerism', 'oil on canvas', 'Accademia Nazionale di San Luca, Rome', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/rh87rnegar.jpg', 'Lavinia Fontana shows herself playing music while a maid holds the sheet music. The picture says: this painter is also an educated young woman.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('ra4mnf79wu', 'daily:written-out:1772-johan-zoffany-the-academicians-of-the-royal-academy', 'The Academicians of the Royal Academy', 'Johan Zoffany', 1772, '1771–1772', null, 'oil on canvas', 'Royal Collection, Windsor', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/ra4mnf79wu.jpg', 'The members of the new Royal Academy in London gather around a nude model in the life class. Two founding members are women, Angelica Kauffman and Mary Moser, but they only appear as small portraits on the wall.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('dm8kz25pp6', 'daily:written-out:1639-artemisia-gentileschi-self-portrait-as-the-allegory-of-paintin', 'Self-Portrait as the Allegory of Painting', 'Artemisia Gentileschi', 1639, '1638–1639', 'Baroque', 'oil on canvas', 'Royal Collection, Hampton Court Palace', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/dm8kz25pp6.jpg', 'Artemisia Gentileschi painted herself as the figure of Painting, brush in hand and hard at work. She probably made it during her stay in England, and King Charles I owned it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('tk34mfb7dj', 'daily:written-out:1872-berthe-morisot-the-cradle', 'The Cradle', 'Berthe Morisot', 1872, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/tk34mfb7dj.jpg', 'Berthe Morisot painted her sister Edma watching over her sleeping baby, Blanche. The picture hung in the first Impressionist exhibition.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('8cyrccbgzw', 'daily:written-out:1782-lisabeth-vig-e-le-brun-self-portrait-in-a-straw-hat', 'Self-Portrait in a Straw Hat', 'Élisabeth Vigée Le Brun', 1782, 'after 1782', null, 'oil on canvas', 'National Gallery, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/8cyrccbgzw.jpg', 'On a trip to Flanders Élisabeth Vigée Le Brun saw Rubens'' portrait of a woman in a straw hat and painted her own answer to it. She became Queen Marie Antoinette''s favourite portrait painter.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-08', 'written-out', 'Written out of the picture', 'Aus dem Bild gedrängt', 'Today''s ten pictures were all made by women, except one, and that one tells you a lot. Each of these women was famous in her day and was then pushed to the edge of the frame. Your start card is a page from Maria Sibylla Merian''s insect book. The first picture to place shows three sisters at a chessboard.', 'Die zehn Bilder von heute haben alle Frauen gemacht, bis auf eins, und genau das verrät viel. Jede dieser Frauen war zu Lebzeiten berühmt und wurde danach an den Bildrand gedrängt. Deine Startkarte ist eine Seite aus Maria Sibylla Merians Insektenbuch. Das erste Bild zum Einordnen zeigt drei Schwestern am Schachbrett.', 'Every woman today was celebrated in her lifetime, and many of them then went missing from the big art history books. Museums around the world are now bringing them back into the picture, one exhibition at a time.', 'Jede Frau von heute wurde zu Lebzeiten gefeiert, und viele verschwanden danach aus den großen Kunstgeschichtsbüchern. Museen auf der ganzen Welt holen sie jetzt zurück ins Bild, eine Ausstellung nach der anderen.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 0, '7drh4hwm49', null, null, 'Maria Sibylla Merian, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 1, '4uwrrhee7q', 'Sofonisba went on to work at the Spanish court and painted the royal family. Our next painter chose to hide her boldest pictures herself.', 'Sofonisba arbeitete dann am spanischen Hof und malte die Königsfamilie. Unsere nächste Malerin hat ihre kühnsten Bilder selbst versteckt.', 'Sofonisba Anguissola, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 2, 'mj9ubupv5k', 'Hilma af Klint asked that her abstract work stay hidden for twenty years following her death, so the world met it very late. The next painter vanished in another way: under a famous man''s name.', 'Hilma af Klint wollte, dass ihre abstrakten Bilder bis zwanzig Jahre nach ihrem Tod verborgen bleiben, und so lernte die Welt sie erst sehr spät kennen. Die nächste Malerin verschwand auf andere Weise: unter dem Namen eines berühmten Mannes.', 'Hilma af Klint, public domain (photo: Hilma af Klint Foundation, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 3, 'g9dab98dr3', 'For a long time Leyster''s pictures were sold as works by Frans Hals, and only in 1893 was she rediscovered. The next painter made sure nobody could overlook her: she painted big.', 'Lange wurden Leysters Bilder als Werke von Frans Hals verkauft, erst 1893 wurde sie wiederentdeckt. Die nächste Malerin sorgte dafür, dass niemand sie übersehen konnte: Sie malte riesig.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 4, '7a5wukj2sf', 'Rosa Bonheur became the first woman artist to receive the Legion of Honour. From the noisy horse market we go to a quiet room, where a young woman sits at a keyboard.', 'Rosa Bonheur bekam als erste Künstlerin das Kreuz der Ehrenlegion. Vom lauten Pferdemarkt geht es in einen stillen Raum, in dem eine junge Frau an einem Tasteninstrument sitzt.', 'The Metropolitan Museum of Art, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 5, 'rh87rnegar', 'Lavinia Fontana went on to Rome as a sought-after portrait painter while raising a large family. Next comes the one picture by a man today. Look closely at who is missing.', 'Lavinia Fontana zog als gefragte Porträtmalerin nach Rom und zog nebenbei eine große Familie groß. Jetzt kommt das einzige Bild eines Mannes heute. Schau genau hin, wer fehlt.', 'Lavinia Fontana, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 6, 'ra4mnf79wu', 'A lady was not allowed into the life class, so the two women could only hang on the wall. The next woman put herself right in the middle of the picture, as Painting itself.', 'Eine Dame durfte beim Aktzeichnen nicht dabei sein, also konnten die beiden Frauen nur an der Wand hängen. Die nächste Frau hat sich mitten ins Bild gesetzt, als die Malerei selbst.', 'Johan Zoffany, public domain (Royal Collection, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 7, 'dm8kz25pp6', 'Artemisia was famous across Europe in her lifetime, and then she almost disappeared from the books. Our next painter turned her brush on her own family.', 'Artemisia war zu Lebzeiten in ganz Europa berühmt und verschwand danach fast aus den Büchern. Unsere nächste Malerin hat ihre eigene Familie gemalt.', 'Artemisia Gentileschi, public domain (Royal Collection, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 8, 'tk34mfb7dj', 'Morisot took part in nearly every Impressionist exhibition. Our final picture is a self-portrait in a straw hat.', 'Morisot war bei fast allen Ausstellungen der Impressionisten dabei. Unser letztes Bild ist ein Selbstporträt mit Strohhut.', 'Musée d''Orsay, public domain (Google Art Project, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 9, '8cyrccbgzw', 'And that is the end of our gallery.', 'Damit endet unser Rundgang durch die Galerie.', 'National Gallery, London, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('wwgwkshzxs', 'daily:saint-martin:1567-pieter-bruegel-the-elder-the-wine-of-saint-martin-s-day', 'The Wine of Saint Martin''s Day', 'Pieter Bruegel the Elder', 1567, '1566–1567 (Prado); Wikipedia gives c. 1565–1568', 'Northern Renaissance', 'glue-size tempera on linen', 'Museo del Prado, Madrid', 2, 'painting', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Bruegelsanmartin.jpg/1280px-Bruegelsanmartin.jpg', 'A whole village crowds round a barrel of new wine, and somewhere in the throng St Martin quietly shares his cloak. Experts found traces of Bruegel''s signature on it in 2010, and the Prado bought the picture that same year.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('uxjczc23qj', 'daily:saint-martin:1317-simone-martini-saint-martin-shares-his-cloak-with-a-beg', 'Saint Martin Shares His Cloak with a Beggar', 'Simone Martini', 1317, 'the chapel frescoes are undated; about 1313–1318 (Wikipedia), about 1316–1317 (Key to Umbria)', 'Sienese School', 'fresco', 'San Martino Chapel, Lower Basilica of San Francesco, Assisi', 3, 'painting', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Simone_Martini_033.jpg/1280px-Simone_Martini_033.jpg', 'This scene opens a series of ten frescoes about Martin''s life in a chapel of the Lower Basilica in Assisi. A cardinal paid for the chapel, but Simone Martini neither signed nor dated his paintings.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('8267g92wvy', 'daily:saint-martin:1599-el-greco-saint-martin-and-the-beggar', 'Saint Martin and the Beggar', 'El Greco', 1599, '1597–1599', 'Mannerism', 'oil on canvas', 'National Gallery of Art, Washington', 2, 'painting', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/El_Greco_%28Domenikos_Theotokopoulos%29%2C_Saint_Martin_and_the_Beggar%2C_1597-1599%2C_NGA_1164.jpg/1280px-El_Greco_%28Domenikos_Theotokopoulos%29%2C_Saint_Martin_and_the_Beggar%2C_1597-1599%2C_NGA_1164.jpg', 'Martín Ramírez, who shared the saint''s name, ordered this picture for his chapel of San José in Toledo. It stayed there for about three hundred years before it went to America.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('t3n2tp76g6', 'daily:saint-martin:1240-naumburg-master-attributed-bassenheim-rider', 'Bassenheim Rider', 'Naumburg Master (attributed)', 1240, 'about 1240: the plaque in Bassenheim says 1239, the regional tourism site says the master worked in Mainz around 1250', null, 'sandstone relief', 'Parish church of St Martin, Bassenheim', 3, 'sculpture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Bassenheimer_Reiter_%282009-10-19_Sp%29.JPG/1280px-Bassenheimer_Reiter_%282009-10-19_Sp%29.JPG', 'This grey sandstone relief is attributed to the Naumburg Master, one of the great sculptors of the Middle Ages. Martin leans down from his horse to share his cloak with the beggar.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('f6xavxx6wj', 'daily:saint-martin:1900-gebhard-fugel-saint-martin-and-the-beggar', 'Saint Martin and the Beggar', 'Gebhard Fugel', 1900, '1900 (Commons); Panorama Altötting dates his murals in the Wangen town church to 1899', null, 'ceiling painting', 'Parish church of St Martin, Wangen im Allgäu', 3, 'painting', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Wangen_Pfarrkirche_St_Martinus_Decke_St_Martin_und_der_Arme.jpg/1280px-Wangen_Pfarrkirche_St_Martinus_Decke_St_Martin_und_der_Arme.jpg', 'Gebhard Fugel painted this scene on the ceiling of St Martin''s church in Wangen im Allgäu. He was born near Ravensburg, not far away, and painted churches in southern Germany and Austria.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('gnznszywvc', 'daily:saint-martin:1475-martin-schongauer-saint-martin-dividing-his-cloak', 'Saint Martin Dividing His Cloak', 'Martin Schongauer', 1475, 'about 1475', 'Northern Renaissance', 'engraving', 'National Gallery of Art, Washington', 3, 'drawing', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Martin_Schongauer%2C_Saint_Martin_Dividing_His_Cloak%2C_c._1475%2C_NGA_3275.jpg/1280px-Martin_Schongauer%2C_Saint_Martin_Dividing_His_Cloak%2C_c._1475%2C_NGA_3275.jpg', 'This engraving is only about fifteen centimetres tall. Because it was printed from an engraved metal plate, the same little Martin could be printed again and again.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('2vezsr9kp2', 'daily:saint-martin:1620-anthony-van-dyck-saint-martin-dividing-his-cloak', 'Saint Martin Dividing his Cloak', 'Anthony van Dyck', 1620, 'about 1618–1620 (Royal Collection); Wikipedia gives about 1620', 'Baroque', 'oil on canvas', 'Royal Collection, Windsor Castle', 2, 'painting', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Anthony_van_Dyck_%281599-1641%29_-_St_Martin_Dividing_his_Cloak_-_RCIN_405878_-_Royal_Collection.jpg/1280px-Anthony_van_Dyck_%281599-1641%29_-_St_Martin_Dividing_his_Cloak_-_RCIN_405878_-_Royal_Collection.jpg', 'Van Dyck painted a smaller version of this scene for the church in Zaventem near Brussels, and it still hangs there. This bigger one, more than two metres wide, belongs to the British Royal Collection.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-11', 'saint-martin', 'Half a cloak', 'Ein halber Mantel', 'Today is St Martin''s Day, and children all over the country walk with lanterns. We follow one moment that artists never got tired of: a young soldier cuts his cloak in half for a freezing beggar. Your start card is a wild village feast in Martin''s honour, and the first picture to place takes you to a chapel in Italy.', 'Heute ist Martinstag, und überall ziehen Kinder mit Laternen durch die Straßen. Wir folgen einem Moment, von dem Künstler nie genug bekamen: Ein junger Soldat teilt seinen Mantel für einen frierenden Bettler. Deine Startkarte ist ein wildes Dorffest zu Martins Ehren, und das erste Bild zum Einordnen führt dich in eine Kapelle in Italien.', 'Every age dressed Martin and his beggar in its own way, but the gesture stayed the same. Tonight his story lives on in lantern walks and in many a roast goose.', 'Jede Zeit hat Martin und seinen Bettler auf ihre eigene Weise gekleidet, doch die Geste blieb dieselbe. Heute Abend lebt seine Geschichte in Laternenumzügen weiter und in so mancher Martinsgans.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 0, 'wwgwkshzxs', null, null, 'Museo del Prado, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 1, 'uxjczc23qj', 'Simone Martini painted Martin''s whole life on these chapel walls. Next we travel to Toledo in Spain, where a man called Martín wanted his patron saint over his altar.', 'Simone Martini hat Martins ganzes Leben an diese Kapellenwände gemalt. Als Nächstes reisen wir nach Toledo in Spanien, wo ein Mann namens Martín seinen Namenspatron über dem Altar haben wollte.', 'Simone Martini, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 2, '8267g92wvy', 'El Greco puts Martin in shining armour on a white horse, high above the beggar. Our next Martin is not painted at all: he is carved in stone.', 'El Greco setzt Martin in glänzender Rüstung auf ein weißes Pferd, hoch über den Bettler. Unser nächster Martin ist gar nicht gemalt: Er ist in Stein gehauen.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 3, 't3n2tp76g6', 'In 1683 the rider came to the village of Bassenheim, and he still lives in its parish church. Now look up: our next Martin rides across a church ceiling in the Allgäu.', '1683 kam der Reiter in das Dorf Bassenheim, und er wohnt bis heute in der Pfarrkirche dort. Jetzt schau nach oben: Unser nächster Martin reitet über eine Kirchendecke im Allgäu.', 'Photo: Lothar Spurzem, CC BY-SA 2.0 de');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 4, 'f6xavxx6wj', 'Fugel also painted a giant panorama of the Crucifixion for Altötting. Our next Martin is tiny by comparison: he fits on a sheet of paper smaller than your hand.', 'Fugel malte auch ein riesiges Panorama der Kreuzigung für Altötting. Unser nächster Martin ist dagegen winzig: Er passt auf ein Blatt Papier, das kleiner ist als deine Hand.', 'Gebhard Fugel, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 5, 'gnznszywvc', 'Schongauer shared his name with the saint, a nice coincidence for this card. Our final Martin comes from Antwerp, a city full of painters.', 'Schongauer trug denselben Vornamen wie der Heilige, ein schöner Zufall für diese Karte. Unser letzter Martin kommt aus Antwerpen, einer Stadt voller Maler.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 6, '2vezsr9kp2', 'And with that, our lantern walk ends.', 'Damit endet unser Laternenumzug.', 'Royal Collection Trust, public domain (Wikimedia Commons)');
